package com.fakelegacy.order.events;

import java.math.BigDecimal;
import java.math.RoundingMode;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Component;

import com.fakelegacy.order.client.CustomerClient;
import com.fakelegacy.order.client.RemoteResult;
import com.fakelegacy.order.domain.Order;

@Component
public class LoyaltyListener {

    private static final Logger log = LoggerFactory.getLogger(LoyaltyListener.class);
    private static final BigDecimal POINT_VALUE = new BigDecimal("0.05");

    @Autowired
    private CustomerClient customerClient;

    /** earned = floor(goodsHt x share of the goods paid with money); shipping is excluded. */
    @EventListener
    public void onOrderPaid(OrderPaidEvent event) {
        Order order = event.getOrder();
        BigDecimal redeemedValue = POINT_VALUE.multiply(BigDecimal.valueOf(order.getRedeemedPoints()));
        BigDecimal paidShare = order.getGoodsTtc().subtract(redeemedValue);
        int points = order.getGoodsHt().multiply(paidShare)
                .divide(order.getGoodsTtc(), 0, RoundingMode.DOWN).intValue();
        if (points <= 0) {
            return;
        }
        RemoteResult r = customerClient.earn(order.getCustomerId(), points, order.getReference());
        if (!r.isOk()) {
            log.warn("could not credit loyalty points for {}: {}", order.getReference(), r.getMessage());
            return;
        }
        // business customers are ignored by customer-service, "credited" is then 0
        order.setEarnedPoints(((Number) r.getBody().get("credited")).intValue());
    }
}
